def submit(clientId, seq, baseRev, op):
    if dedupe.get(clientId, -1) >= seq:
        return Ack(seq, dedupe_rev[clientId])      # retry of committed op
    if baseRev < log_floor:                         # too old, history trimmed
        return Error('RESYNC')
    for r in range(baseRev + 1, self.rev + 1):
        op, _ = transform(op, history[r], side='right')
    new_rev = self.rev + 1
    oplog.append(doc_id, new_rev, epoch, op)       # conditional, quorum
    self.doc = apply(self.doc, op); self.rev = new_rev
    history[new_rev] = op; dedupe[clientId] = seq
    broadcast(new_rev, op, except_client=clientId)
    return Ack(seq, new_rev)

state: inflight=None, buffer=None, rev
on_local(op):
    apply_to_editor(op)
    if inflight is None: inflight = op; send(op, rev)
    else: buffer = op if buffer is None else compose(buffer, op)
on_ack(new_rev):
    rev = new_rev; inflight = buffer; buffer = None
    if inflight: send(inflight, rev)
on_remote(new_rev, op):
    if inflight: inflight, op = transform(inflight, op)
    if buffer:   buffer, op = transform(buffer, op)
    apply_to_editor(op); rev = new_rev

def xform_ins_ins(a, b, a_wins_tie):
    if a.pos < b.pos or (a.pos == b.pos and a_wins_tie):
        return a, Insert(b.pos + len(a.text), b.text)
    return Insert(a.pos + len(b.text), a.text), b

def maybe_snapshot():
    if self.rev - last_snap_rev >= 500 or idle_for(300):
        blob.put(f'snapshots/{doc}/{self.rev}', encode(self.doc))
        meta.cas(doc, 'lastSnapshotRev', last_snap_rev, self.rev)
        last_snap_rev = self.rev
